package main

import (
	"bufio"
	"fmt"
	"os"
	"strconv"
	"strings"

	"github.com/shopspring/decimal"
)

type DiscRec struct { // 01 DISC-REC, 15 bytes
	DrItem  string          // PIC X(6) @0 len=6
	DrPrice decimal.Decimal // PIC 9(5)V99 @6 len=7
	DrPct   int64           // PIC 9(2) @13 len=2
}

// Standalone working-storage items (VALUE shown after '=')
var WsEofFlag string = "N"                       // PIC X len=1 = "N"
var WsDiscount decimal.Decimal = decimal.Zero     // PIC 9(5)V99 len=7 = 0
var WsNet decimal.Decimal = decimal.Zero          // PIC 9(5)V99 len=7 = 0
var WsTotalNet decimal.Decimal = decimal.Zero     // PIC 9(8)V99 len=10 = 0
var WsCount int64 = 0                             // PIC 9(3) len=3 = 0
var WsPriceEd string                              // PIC ZZ,ZZ9.99 len=9
var WsDiscEd string                               // PIC ZZ,ZZ9.99 len=9
var WsNetEd string                                // PIC ZZ,ZZ9.99 len=9
var WsTotalEd string                              // PIC ZZ,ZZZ,ZZ9.99 len=13

var discRec DiscRec
var inputFile *os.File
var scanner *bufio.Scanner

func parseDecimalField(raw string, scale int32) decimal.Decimal {
	s := strings.TrimSpace(raw)
	if s == "" {
		return decimal.Zero
	}
	d, err := decimal.NewFromString(s)
	if err != nil {
		return decimal.Zero
	}
	return d.Shift(-scale)
}

func parseIntField(raw string) int64 {
	s := strings.TrimSpace(raw)
	if s == "" {
		return 0
	}
	v, err := strconv.ParseInt(s, 10, 64)
	if err != nil {
		return 0
	}
	return v
}

func normalizeDecimal(v decimal.Decimal, intDigits int, scale int32) decimal.Decimal {
	if intDigits+int(scale) == 0 {
		return decimal.Zero
	}
	isNeg := v.Sign() < 0
	av := v.Abs()
	// scaled = |v| * 10^scale, truncated to integer
	scaled := av.Shift(scale).Truncate(0)
	totalDigits := intDigits + int(scale)
	divisor := decimal.New(1, int32(totalDigits)) // 10^totalDigits
	var scaledMod decimal.Decimal
	if totalDigits > 0 {
		scaledMod = scaled.Mod(divisor)
	} else {
		scaledMod = decimal.Zero
	}
	resAbs := scaledMod.Shift(-scale)
	if isNeg {
		// keep sign: low-order digits with negative sign
		// Mod already positive, apply negative
		resAbs = resAbs.Neg()
		// Remove negative zero
		if resAbs.IsZero() {
			resAbs = decimal.Zero
		}
	}
	return resAbs
}

func formatEdited(v decimal.Decimal, pic string) string {
	dotIdx := strings.Index(pic, ".")
	var intPic, fracPic string
	if dotIdx != -1 {
		intPic = pic[:dotIdx]
		fracPic = pic[dotIdx+1:]
	} else {
		intPic = pic
		fracPic = ""
	}
	intDigits := 0
	for _, ch := range intPic {
		if ch == 'Z' || ch == '9' {
			intDigits++
		}
	}
	fracDigits := 0
	for _, ch := range fracPic {
		if ch == 'Z' || ch == '9' {
			fracDigits++
		}
	}
	totalDigits := intDigits + fracDigits

	av := v.Abs()
	// overflow handling for edited field : keep low-order totalDigits
	divisor := decimal.New(1, int32(totalDigits))
	scaled := av.Shift(int32(fracDigits)).Truncate(0)
	var scaledMod decimal.Decimal
	if totalDigits > 0 {
		scaledMod = scaled.Mod(divisor)
	} else {
		scaledMod = decimal.Zero
	}
	scaledStr := scaledMod.StringFixed(0)
	// StringFixed may contain minus sign? av is positive so no
	// Ensure no decimal point present
	if idx := strings.Index(scaledStr, "."); idx != -1 {
		scaledStr = scaledStr[:idx]
	}
	if len(scaledStr) < totalDigits {
		scaledStr = strings.Repeat("0", totalDigits-len(scaledStr)) + scaledStr
	}
	var intStr, fracStr string
	if fracDigits > 0 {
		if intDigits > 0 {
			intStr = scaledStr[:intDigits]
		}
		fracStr = scaledStr[intDigits:]
	} else {
		intStr = scaledStr
		fracStr = ""
	}

	// build integer part with commas
	resInt := make([]byte, len(intPic))
	digitIdx := 0
	for i, ch := range intPic {
		if ch == 'Z' || ch == '9' {
			if digitIdx < len(intStr) {
				resInt[i] = intStr[digitIdx]
			} else {
				resInt[i] = '0'
			}
			digitIdx++
		} else if ch == ',' {
			resInt[i] = ','
		} else {
			resInt[i] = byte(ch)
		}
	}
	suppressed := true
	for i, picCh := range intPic {
		switch picCh {
		case 'Z':
			if suppressed && resInt[i] == '0' {
				resInt[i] = ' '
			} else {
				suppressed = false
			}
		case '9':
			suppressed = false
		case ',':
			if suppressed {
				resInt[i] = ' '
			}
		}
	}
	if dotIdx != -1 {
		return string(resInt) + "." + fracStr
	}
	return string(resInt)
}

func MainPara() {
	f, err := os.Open("input.dat")
	if err != nil {
		fmt.Fprintf(os.Stderr, "open input.dat: %v\n", err)
		os.Exit(1)
	}
	inputFile = f
	scanner = bufio.NewScanner(f)
	// allow large lines
	const maxCapacity = 1024 * 1024
	buf := make([]byte, 0, 64*1024)
	scanner.Buffer(buf, maxCapacity)

	READPARA()
	for WsEofFlag != "Y" {
		PROCESSPARA()
	}
	scanner = nil
	inputFile.Close()
	SUMMARYPARA()
}

func READPARA() {
	if scanner.Scan() {
		line := scanner.Text()
		// Scanner strips \n and handles \r\n, but keep handling of \r left
		// If original file had \r, Scanner already removed it.
		var recLine string
		if len(line) < 15 {
			recLine = line + strings.Repeat(" ", 15-len(line))
		} else if len(line) > 15 {
			recLine = line[:15]
		} else {
			recLine = line
		}
		discRec.DrItem = recLine[0:6]
		drPriceRaw := recLine[6:13]
		drPctRaw := recLine[13:15]
		discRec.DrPrice = parseDecimalField(drPriceRaw, 2)
		discRec.DrPct = parseIntField(drPctRaw)
	} else {
		if err := scanner.Err(); err != nil {
			fmt.Fprintf(os.Stderr, "read error: %v\n", err)
			os.Exit(1)
		}
		WsEofFlag = "Y"
	}
}

func PROCESSPARA() {
	// COMPUTE WS-DISCOUNT ROUNDED = DR-PRICE * DR-PCT / 100
	tmp := discRec.DrPrice.Mul(decimal.NewFromInt(discRec.DrPct))
	unrounded := tmp.Shift(-2)
	rounded := unrounded.Round(2)
	WsDiscount = normalizeDecimal(rounded, 5, 2)

	// COMPUTE WS-NET = DR-PRICE - WS-DISCOUNT
	diff := discRec.DrPrice.Sub(WsDiscount)
	truncatedDiff := diff.Truncate(2)
	WsNet = normalizeDecimal(truncatedDiff, 5, 2)

	// ADD WS-NET TO WS-TOTAL-NET
	sum := WsTotalNet.Add(WsNet)
	truncatedSum := sum.Truncate(2)
	WsTotalNet = normalizeDecimal(truncatedSum, 8, 2)

	// ADD 1 TO WS-COUNT
	WsCount = WsCount + 1
	if WsCount >= 1000 || WsCount < 0 {
		WsCount = WsCount % 1000
		if WsCount < 0 {
			WsCount += 1000
		}
	}

	WsPriceEd = formatEdited(discRec.DrPrice, "ZZ,ZZ9.99")
	WsDiscEd = formatEdited(WsDiscount, "ZZ,ZZ9.99")
	WsNetEd = formatEdited(WsNet, "ZZ,ZZ9.99")

	pctStr := fmt.Sprintf("%02d", discRec.DrPct)
	line := discRec.DrItem + " " + WsPriceEd + " " + pctStr + "% " + WsDiscEd + " " + WsNetEd + "\n"
	_, err := os.Stdout.WriteString(line)
	if err != nil {
		fmt.Fprintf(os.Stderr, "write error: %v\n", err)
		os.Exit(1)
	}
	READPARA()
}

func SUMMARYPARA() {
	WsTotalEd = formatEdited(WsTotalNet, "ZZ,ZZZ,ZZ9.99")
	countStr := fmt.Sprintf("%03d", WsCount)
	line := "ITEMS: " + countStr + " NET TOTAL: " + WsTotalEd + "\n"
	_, err := os.Stdout.WriteString(line)
	if err != nil {
		fmt.Fprintf(os.Stderr, "write error: %v\n", err)
		os.Exit(1)
	}
}

func main() {
	MainPara()
}
